acceptance_tests.tests/test_acceptance_display_width_unic:
"""Hidden acceptance tests for task ``textkit-display-width-unicode``."""

import pytest

from textkit.width import display_width, pad


def test_wide_characters_take_two_columns():
    assert display_width("日本") == 4


def test_fullwidth_and_halfwidth_forms():
    assert display_width("\uff21\uff71") == 3


def test_emoji_is_wide():
    assert display_width("ok😀") == 4


def test_combining_marks_take_no_columns():
    assert display_width("cafe\u0301") == 4


def test_zero_width_format_characters_take_no_columns():
    assert display_width("a\u200bb\u200dc\ufeff") == 3


def test_pad_wide_text_left_and_right():
    assert pad("日本", 6) == "日本  "
    assert pad("日本", 6, "right") == "  日本"


def test_pad_counts_combining_marks_as_zero():
    assert pad("cafe\u0301", 6) == "cafe\u0301  "


def test_wide_text_already_at_width_is_unchanged():
    assert pad("日本語", 4) == "日本語"


def test_center_puts_the_extra_space_on_the_right():
    assert pad("ab", 5, "center") == " ab  "


def test_unknown_alignment_raises_value_error():
    with pytest.raises(ValueError):
        pad("ab", 4, "middle")

"""Hidden acceptance tests for task ``textkit-indent-skip-blank``."""

from textkit.indent import indent


def test_skip_blank_leaves_empty_lines_alone():
    assert indent("a\n\nb\n", "> ", skip_blank=True) == "> a\n\n> b\n"


def test_skip_blank_leaves_whitespace_only_lines_alone():
    assert indent("a\n   \n\tb", "> ", skip_blank=True) == "> a\n   \n> \tb"


def test_skip_blank_preserves_crlf():
    assert indent("a\r\n\r\nb", "# ", skip_blank=True) == "# a\r\n\r\n# b"


def test_skip_blank_false_matches_default_behaviour():
    assert indent("a\n\nb", "> ", skip_blank=False) == "> a\n> \n> b"


def test_skip_blank_on_text_without_blank_lines():
    assert indent("x\ny", "  ", skip_blank=True) == "  x\n  y"

acceptance_tests.tests/test_acceptance_line_range_inclusi:
"""Hidden acceptance tests for task ``textkit-line-range-inclusive``."""

from textkit.lines import line_range

TEXT = "alpha\nbeta\ngamma\ndelta"


def test_middle_range_is_inclusive():
    assert line_range(TEXT, 2, 3) == ["beta", "gamma"]


def test_single_first_line():
    assert line_range(TEXT, 1, 1) == ["alpha"]


def test_whole_text():
    assert line_range(TEXT, 1, 4) == ["alpha", "beta", "gamma", "delta"]


def test_last_is_clamped_to_the_end():
    assert line_range(TEXT, 3, 99) == ["gamma", "delta"]


def test_single_line_text():
    assert line_range("only", 1, 1) == ["only"]


def test_crlf_line_endings_are_not_included():
    assert line_range("a\r\nb\r\nc\r\n", 2, 3) == ["b", "c"]

acceptance_tests.tests/test_acceptance_parse_pairs_errors:
"""Hidden acceptance tests for task ``textkit-parse-pairs-errors``."""

import pytest

from textkit.pairs import ParseError, parse_pairs


def test_segment_without_equals_raises_parse_error():
    with pytest.raises(ParseError):
        parse_pairs("a=1;oops;b=2")


def test_missing_equals_is_still_a_value_error():
    with pytest.raises(ValueError):
        parse_pairs("novalue")


def test_empty_key_raises_parse_error():
    with pytest.raises(ParseError):
        parse_pairs("=1")


def test_blank_key_raises_parse_error():
    with pytest.raises(ParseError):
        parse_pairs("a=1;   = 2")


def test_error_message_names_the_offending_segment():
    with pytest.raises(ParseError, match="broken-segment"):
        parse_pairs("a=1; broken-segment ;b=2")


def test_value_may_contain_equals_signs():
    assert parse_pairs("url=https://x.test/?q=1&r=2") == {"url": "https://x.test/?q=1&r=2"}

acceptance_tests.tests/test_acceptance_slug_collapse.py:
"""Hidden acceptance tests for task ``textkit-slugify-collapse``.

Stored outside the benchmark repository so the agent never sees it: this
directory is not copied into the sandbox during the agent phase. The grading
engine injects the file into the workspace immediately before running tests.
"""

from textkit import slugify


def test_collapses_repeated_separators():
    assert slugify("Hello,  World!") == "hello-world"


def test_strips_leading_and_trailing_separators():
    assert slugify("  Hello  ") == "hello"


def test_punctuation_runs_collapse():
    assert slugify("a---b") == "a-b"


def test_only_punctuation_yields_empty_slug():
    assert slugify("!!!") == ""


def test_custom_separator_also_collapses():
    assert slugify("Hello,  World!", sep="_") == "hello_world"

